import json
from pathlib import Path

p = Path(__file__).resolve().parent / 'book/manifest.json'
m = json.loads(p.read_text())
data = {
    'en': ('A New Era of Finance: The Bitcoin Standard', 'From barter and monetary metals to fiat money and Bitcoin', 'Barter struggles when traders need different goods. Early communities used shells, livestock, and other exchange objects. Gold and silver supplied durable and scarce monetary metals. Fiat currency shifted control of supply to governments. Bitcoin proposes a fixed supply and decentralized transactions. The book tests money through scarcity, trust, and individual autonomy.', 'The book follows the history of money to explain its argument for Bitcoin. It starts with barter and the difficulty of finding a matching trading partner, then examines early exchange goods and the social trust behind their use. Gold and silver offer a comparison based on durability, portability, divisibility, and scarcity. The account next considers metal-backed currency and the move toward government-issued fiat money. It argues that the ability to expand supply can erode purchasing power and financial autonomy. Bitcoin appears as a digital alternative with a fixed maximum supply and decentralized transaction rules. The conclusion recognizes questions about environmental impact, scale, and regulation while returning to the importance of trust.'),
    'ro': ('O nouă eră a finanțelor: standardul Bitcoin', 'De la troc și metale monetare la banii fiduciari și Bitcoin', 'Trocul devine dificil când partenerii doresc bunuri diferite. Comunitățile timpurii foloseau scoici, animale și alte obiecte de schimb. Aurul și argintul ofereau metale monetare durabile și rare. Moneda fiduciară a mutat controlul ofertei către guverne. Bitcoin propune o ofertă fixă și tranzacții descentralizate. Cartea examinează banii prin raritate, încredere și autonomie personală.', 'Cartea urmărește istoria banilor pentru a explica argumentul său în favoarea Bitcoin. Începe cu trocul și dificultatea de a găsi un partener cu nevoi complementare, apoi analizează primele bunuri folosite la schimb și încrederea socială din spatele lor. Aurul și argintul oferă o comparație întemeiată pe durabilitate, portabilitate, divizibilitate și raritate. Textul discută apoi moneda susținută de metale și trecerea la banii fiduciari emiși de guverne. Susține că extinderea ofertei poate eroda puterea de cumpărare și autonomia financiară. Bitcoin apare ca alternativă digitală cu ofertă maximă fixă și reguli descentralizate pentru tranzacții. Concluzia recunoaște întrebările privind mediul, scalabilitatea și reglementarea, revenind la importanța încrederii.'),
    'fr': ('Une nouvelle ère de la finance : l’étalon Bitcoin', 'Du troc et des métaux monétaires à la monnaie fiduciaire et au Bitcoin', 'Le troc échoue lorsque les partenaires recherchent des biens différents. Les premières communautés utilisaient coquillages, bétail et autres objets d’échange. L’or et l’argent offraient des métaux monétaires durables et rares. La monnaie fiduciaire a confié l’offre aux gouvernements. Bitcoin propose une offre fixe et des transactions décentralisées. Le livre examine la monnaie par la rareté, la confiance et l’autonomie.', 'Ce livre parcourt l’histoire de la monnaie pour expliquer son argument en faveur de Bitcoin. Il commence par le troc et la difficulté de trouver un partenaire aux besoins complémentaires, puis examine les premiers biens d’échange et la confiance sociale qui soutenait leur usage. L’or et l’argent fournissent une comparaison fondée sur la durabilité, la portabilité, la divisibilité et la rareté. Le texte aborde ensuite les monnaies adossées aux métaux et le passage à la monnaie fiduciaire émise par les États. Il soutient que l’expansion de l’offre peut éroder le pouvoir d’achat et l’autonomie financière. Bitcoin apparaît comme une solution numérique à offre maximale fixe et à transactions décentralisées. La conclusion reconnaît les questions environnementales, techniques et réglementaires tout en revenant à l’importance de la confiance.'),
    'de': ('Eine neue Ära der Finanzen: Der Bitcoin-Standard', 'Von Tauschhandel und Geldmetallen zu Fiatgeld und Bitcoin', 'Tauschhandel scheitert oft an unterschiedlichen Bedürfnissen der Partner. Frühe Gemeinschaften nutzten Muscheln, Vieh und andere Tauschgüter. Gold und Silber boten haltbare und knappe Geldmetalle. Fiatgeld verlagerte die Kontrolle des Angebots zum Staat. Bitcoin schlägt ein festes Angebot und dezentrale Transaktionen vor. Das Buch untersucht Geld anhand von Knappheit, Vertrauen und Autonomie.', 'Das Buch verfolgt die Geschichte des Geldes, um sein Argument für Bitcoin zu erläutern. Es beginnt mit dem Tauschhandel und der Schwierigkeit, passende Handelspartner zu finden, und betrachtet dann frühe Tauschgüter und das gesellschaftliche Vertrauen hinter ihrer Verwendung. Gold und Silber bieten einen Vergleich nach Haltbarkeit, Transportfähigkeit, Teilbarkeit und Knappheit. Danach behandelt der Text metallgedeckte Währungen und den Übergang zu staatlich ausgegebenem Fiatgeld. Er argumentiert, dass eine Ausweitung des Geldangebots Kaufkraft und finanzielle Selbstbestimmung schwächen kann. Bitcoin erscheint als digitale Alternative mit fester Höchstmenge und dezentralen Transaktionsregeln. Der Schluss erkennt Fragen zu Umweltfolgen, Skalierbarkeit und Regulierung an und kehrt zur Bedeutung des Vertrauens zurück.'),
    'es': ('Una nueva era de las finanzas: el estándar Bitcoin', 'Del trueque y los metales monetarios al dinero fiduciario y Bitcoin', 'El trueque falla cuando los socios buscan bienes distintos. Las primeras comunidades usaban conchas, ganado y otros objetos de intercambio. El oro y la plata ofrecían metales monetarios duraderos y escasos. El dinero fiduciario trasladó el control de la oferta a los gobiernos. Bitcoin propone una oferta fija y transacciones descentralizadas. El libro examina el dinero mediante escasez, confianza y autonomía.', 'El libro recorre la historia del dinero para explicar su argumento a favor de Bitcoin. Empieza con el trueque y la dificultad de encontrar un socio con necesidades complementarias, y después examina los primeros bienes de intercambio y la confianza social que sostenía su uso. El oro y la plata permiten una comparación basada en durabilidad, portabilidad, divisibilidad y escasez. A continuación estudia las monedas respaldadas por metales y el paso al dinero fiduciario emitido por gobiernos. Sostiene que ampliar la oferta puede erosionar el poder adquisitivo y la autonomía financiera. Bitcoin aparece como alternativa digital con oferta máxima fija y reglas descentralizadas de transacción. La conclusión reconoce las preguntas ambientales, técnicas y regulatorias y vuelve a la importancia de la confianza.'),
    'pt': ('Uma nova era das finanças: o padrão Bitcoin', 'Do escambo e dos metais monetários à moeda fiduciária e ao Bitcoin', 'O escambo falha quando os parceiros procuram bens diferentes. As primeiras comunidades usavam conchas, gado e outros objetos de troca. Ouro e prata ofereciam metais monetários duráveis e escassos. A moeda fiduciária transferiu o controlo da oferta para os governos. Bitcoin propõe uma oferta fixa e transações descentralizadas. O livro examina o dinheiro pela escassez, confiança e autonomia.', 'O livro percorre a história do dinheiro para explicar o seu argumento a favor de Bitcoin. Começa pelo escambo e pela dificuldade de encontrar um parceiro com necessidades complementares, depois examina os primeiros bens de troca e a confiança social que sustentava o seu uso. Ouro e prata oferecem uma comparação baseada na durabilidade, portabilidade, divisibilidade e escassez. O texto aborda em seguida as moedas apoiadas em metais e a passagem para o dinheiro fiduciário emitido pelos governos. Argumenta que expandir a oferta pode corroer o poder de compra e a autonomia financeira. Bitcoin surge como alternativa digital com oferta máxima fixa e regras descentralizadas de transação. A conclusão reconhece questões ambientais, técnicas e regulatórias e regressa à importância da confiança.'),
    'it': ('Una nuova era della finanza: lo standard Bitcoin', 'Dal baratto e dai metalli monetari alla moneta fiduciaria e a Bitcoin', 'Il baratto fallisce quando i partner cercano beni diversi. Le prime comunità usavano conchiglie, bestiame e altri oggetti di scambio. Oro e argento offrivano metalli monetari durevoli e scarsi. La moneta fiduciaria spostò il controllo dell’offerta verso i governi. Bitcoin propone un’offerta fissa e transazioni decentralizzate. Il libro esamina il denaro attraverso scarsità, fiducia e autonomia.', 'Il libro ripercorre la storia del denaro per spiegare il suo argomento a favore di Bitcoin. Inizia dal baratto e dalla difficoltà di trovare un partner con bisogni complementari, poi esamina i primi beni di scambio e la fiducia sociale che ne sosteneva l’uso. Oro e argento permettono un confronto basato su durata, portabilità, divisibilità e scarsità. Il testo considera quindi le valute sostenute da metalli e il passaggio alla moneta fiduciaria emessa dai governi. Sostiene che ampliare l’offerta può erodere il potere d’acquisto e l’autonomia finanziaria. Bitcoin appare come alternativa digitale con offerta massima fissa e regole decentralizzate per le transazioni. La conclusione riconosce le questioni ambientali, tecniche e normative, tornando all’importanza della fiducia.'),
    'pl': ('Nowa era finansów: standard Bitcoina', 'Od barteru i metali pieniężnych do waluty fiducjarnej i Bitcoina', 'Barter zawodzi, gdy partnerzy szukają różnych towarów. Wczesne społeczności używały muszli, bydła i innych dóbr wymiany. Złoto i srebro były trwałymi i rzadkimi metalami pieniężnymi. Waluta fiducjarna oddała kontrolę podaży rządom. Bitcoin proponuje stałą podaż i zdecentralizowane transakcje. Książka bada pieniądz poprzez rzadkość, zaufanie i autonomię.', 'Książka śledzi historię pieniądza, aby wyjaśnić swój argument na rzecz Bitcoina. Zaczyna od barteru i trudności znalezienia partnera o pasujących potrzebach, a następnie omawia dawne dobra wymiany oraz zaufanie społeczne stojące za ich użyciem. Złoto i srebro umożliwiają porównanie oparte na trwałości, przenośności, podzielności i rzadkości. Tekst opisuje też waluty oparte na metalach i przejście do pieniądza fiducjarnego emitowanego przez państwo. Utrzymuje, że zwiększanie podaży może osłabiać siłę nabywczą i autonomię finansową. Bitcoin jest przedstawiony jako cyfrowa alternatywa ze stałym limitem podaży i zdecentralizowanymi regułami transakcji. Zakończenie dostrzega pytania o środowisko, skalowalność i regulacje, wracając do znaczenia zaufania.'),
}
for language, (title, subtitle, short, about) in data.items():
    m['title'][language] = title
    m['subtitle'][language] = subtitle
    m['shortDescription'][language] = short
    sentences = about.split('. ')
    m['aboutBook'][language] = ['. '.join(sentences[:3]).rstrip('.') + '.', '. '.join(sentences[3:])]
m['shortDescriptionEditorial'] = {'source': 'human-reviewed', 'reviewed': True}
m['metadataDraft'] = {'sourceSha256': m['metadataDraft']['sourceSha256'], 'reviewRequired': False, 'reviewedAgainst': 'original chapters I–IV, conclusion and bibliography; old project introduction and promotional closing copy excluded'}
p.write_text(json.dumps(m, ensure_ascii=False, indent=2) + '\n')
